// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Interface describing `dlasyf`.
*/
interface Routine {
	/**
	* Computes a partial symmetric indefinite factorization in place.
	*
	* ## Notes
	*
	* -   INFO is numeric and independent of the one-element KB output.
	* -   A positive INFO marks the first encountered exactly-zero D diagonal; the panel still completes.
	* -   Equal adjacent negative signed 1-based pivots describe ordinary 2x2 blocks.
	* -   Only the upper final KB or lower first KB pivot slots are written; other slots are preserved.
	* -   The full A/W views must be injective and in bounds; all four indexed-byte envelopes must be disjoint.
	* -   Every active actual buffer must have intrinsic ordinary ArrayBuffer backing; SharedArrayBuffer views are rejected before routine-owned writes.
	* -   Foreign-addon externally aliased ordinary ArrayBuffers are outside the caller contract.
	* -   The declared typed-array types cannot encode this runtime backing-store precondition.
	* -   For N=0, after scalar and active KB validation, only KB is written to zero; inactive buffers and unused ndarray metadata are not accessed.
	* -   Inactive buffers aliased to KB can observe its backing-byte change; this new empty behavior is not reference parity.
	* -   Finite stored-triangle inputs define the reference-comparison domain; active nonfinite behavior has no universal guarantee.
	*
	* @param order - row-major (101) or column-major (102) layout
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - matrix order, a nonnegative safe integer at most 2147483647
	* @param NB - panel width, a safe integer from 2 to 2147483647
	* @param KB - mutable Int32 output count scalar
	* @param A - input/output square matrix
	* @param LDA - leading dimension of A, at least max(1,N)
	* @param IPIV - signed 1-based ordinary Bunch-Kaufman pivot outputs
	* @param W - mutable N-by-NB output scratch
	* @param LDW - scratch leading dimension, at least N (or 1) column-major and NB row-major
	* @throws selectors and active array types/backing stores must be valid
	* @throws dimensions, active metadata, bounds, collisions and aliases must satisfy the preconditions
	* @returns zero or a positive singular diagonal index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 0.0, 4.0, 999.0, 0.0 ] );
	* var W = new Float64Array( 4 );
	* var P = new Int32Array( 2 );
	* var KB = new Int32Array( 1 );
	*
	* var info = dlasyf( 'row-major', 'upper', 2, 2, KB, A, 2, P, W, 2 );
	* // returns 0
	* // KB => <Int32Array>[ 2 ]
	* // P => <Int32Array>[ -1, -1 ]
	*/
	( order: Layout | 101 | 102, uplo: MatrixTriangle | 121 | 122, N: number, NB: number, KB: Int32Array, A: Float64Array, LDA: number, IPIV: Int32Array, W: Float64Array, LDW: number ): number;

	/**
	* Computes a partial symmetric factorization with alternative indexing semantics.
	*
	* ## Notes
	*
	* -   INFO is numeric and independent of the one-element KB output.
	* -   A positive INFO marks the first encountered exactly-zero D diagonal; the panel still completes.
	* -   Equal adjacent negative signed 1-based pivots describe ordinary 2x2 blocks.
	* -   Only the upper final KB or lower first KB pivot slots are written; other slots are preserved.
	* -   The full A/W views must be injective and in bounds; all four indexed-byte envelopes must be disjoint.
	* -   Every active actual buffer must have intrinsic ordinary ArrayBuffer backing; SharedArrayBuffer views are rejected before routine-owned writes.
	* -   Foreign-addon externally aliased ordinary ArrayBuffers are outside the caller contract.
	* -   The declared typed-array types cannot encode this runtime backing-store precondition.
	* -   For N=0, after scalar and active KB validation, only KB is written to zero; inactive buffers and unused ndarray metadata are not accessed.
	* -   Inactive buffers aliased to KB can observe its backing-byte change; this new empty behavior is not reference parity.
	* -   Finite stored-triangle inputs define the reference-comparison domain; active nonfinite behavior has no universal guarantee.
	*
	* -   Strides and offsets are element indices relative to their actual typed-array views.
	* -   Positive and negative independent strides are supported; mutable zero strides are rejected for axes of extent greater than one.
	*
	* @param uplo - upper (121) or lower (122) stored triangle
	* @param N - matrix order, a nonnegative safe integer at most 2147483647
	* @param NB - panel width, a safe integer from 2 to 2147483647
	* @param KB - mutable Int32 output count scalar
	* @param offsetKB - index of the one active output scalar
	* @param A - input/output square matrix
	* @param strideA1 - matrix row stride
	* @param strideA2 - matrix column stride
	* @param offsetA - starting matrix index
	* @param IPIV - signed 1-based ordinary Bunch-Kaufman pivot outputs
	* @param strideIPIV - pivot stride
	* @param offsetIPIV - starting pivot index
	* @param W - mutable N-by-NB output scratch
	* @param strideW1 - scratch row stride
	* @param strideW2 - scratch column stride
	* @param offsetW - starting scratch index
	* @throws selectors and active array types/backing stores must be valid
	* @throws dimensions, active metadata, bounds, collisions and aliases must satisfy the preconditions
	* @returns zero or a positive singular diagonal index
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var A = new Float64Array( [ 9.0, 0.0, 9.0 ] );
	* var W = new Float64Array( 4 );
	* var P = new Int32Array( [ 8, 0, 8 ] );
	* var KB = new Int32Array( [ 7, 9, 7 ] );
	*
	* var info = dlasyf.ndarray( 'upper', 1, 2, KB, 1, A, 1, 1, 1, P, 1, 1, W, 2, 1, 1 );
	* // returns 1
	* // KB => <Int32Array>[ 7, 1, 7 ]
	* // P => <Int32Array>[ 8, 1, 8 ]
	*/
	ndarray( uplo: MatrixTriangle | 121 | 122, N: number, NB: number, KB: Int32Array, offsetKB: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number, IPIV: Int32Array, strideIPIV: number, offsetIPIV: number, W: Float64Array, strideW1: number, strideW2: number, offsetW: number ): number;
}

/**
* Computes a partial symmetric indefinite factorization.
*
* @param order - row-major (101) or column-major (102) layout
* @param uplo - upper (121) or lower (122) stored triangle
* @param N - matrix order, a nonnegative safe integer at most 2147483647
* @param NB - panel width, a safe integer from 2 to 2147483647
* @param KB - mutable Int32 output count scalar
* @param A - input/output square matrix
* @param LDA - leading dimension of A, at least max(1,N)
* @param IPIV - signed 1-based ordinary Bunch-Kaufman pivot outputs
* @param W - mutable N-by-NB output scratch
* @param LDW - scratch leading dimension, at least N (or 1) column-major and NB row-major
* @returns numeric INFO, independent of the mutable KB count
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var A = new Float64Array( [ 0.0 ] );
* var W = new Float64Array( 2 );
* var P = new Int32Array( 1 );
* var KB = new Int32Array( 1 );
*
* var info = dlasyf( 'column-major', 'lower', 1, 2, KB, A, 1, P, W, 1 );
* // returns 1
* // KB => <Int32Array>[ 1 ]
*/
declare var dlasyf: Routine;


// EXPORTS //

export = dlasyf;
